package edu.pe.cibertec.saibm.membresia.infrastructure.in.rest;
import java.net.URI; import java.util.stream.Collectors; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class MembershipExceptionHandler {@ExceptionHandler(WriteAuthorizationException.class)ProblemDetail forbidden(HttpServletRequest r){return p(HttpStatus.FORBIDDEN,"Forbidden",r);}@ExceptionHandler({IllegalArgumentException.class,InvalidRequestException.class})ProblemDetail invalid(Exception e,HttpServletRequest r){return p(HttpStatus.BAD_REQUEST,"Invalid request",r);}@ExceptionHandler(IllegalStateException.class)ProblemDetail conflict(HttpServletRequest r){return p(HttpStatus.CONFLICT,"Membership conflict",r);}@ExceptionHandler(MethodArgumentNotValidException.class)ProblemDetail validation(MethodArgumentNotValidException e,HttpServletRequest r){var x=p(HttpStatus.BAD_REQUEST,"Invalid request",r);x.setProperty("errors",e.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(a->a.getField(),a->a.getDefaultMessage(),(a,b)->a)));return x;}private ProblemDetail p(HttpStatus s,String t,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,t);p.setTitle(t);p.setType(URI.create("urn:saibm:membresia:"+s.value()));p.setInstance(URI.create(r.getRequestURI()));return p;}}
